def plus_or_dot(pieces: Union[str, List[str]]) -> str:
    """Return '.' if the closest tag of the pieces contains '+', otherwise, return '+'.

    Args:
        pieces: A string or a list of strings representing tags.

    Returns:
        A string, either '.' or '+' based on the presence of the character '+'.
    """
    if isinstance(pieces, str):
        # Check for '+' in the string
        if '+' in pieces:
            return '.'
    elif isinstance(pieces, list):
        # Iterate through each piece in the list
        for piece in pieces:
            if '+' in piece:
                return '.'

    return '+'

