import re

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size: str, a string representing a human readable file size (e.g., '500K')

    Returns:
        int: file size in bytes

    Raises:
        ValueError: If the size format is invalid.
    """
    # Define a regex pattern to match the size format
    pattern = r'^\s*(\d+(\.\d+)?)\s*([KMGTP]?)\s*$'
    match = re.match(pattern, size, re.IGNORECASE)

    if not match:
        raise ValueError('Error: Invalid size format')

    # Extract the numeric part and the suffix
    num_str, _, suffix = match.groups()
    num = float(num_str)

    # Convert based on the suffix
    suffix = suffix.upper()
    if suffix == 'K':
        return int(num * 1024)
    elif suffix == 'M':
        return int(num * 1024 ** 2)
    elif suffix == 'G':
        return int(num * 1024 ** 3)
    elif suffix == 'T':
        return int(num * 1024 ** 4)
    else:  # No suffix means bytes
        return int(num)

