from typing import Dict, Any

def _dictsum(*dicts: Dict[str, Any]) -> Dict[str, float]:
    """ 
    Sum values with the same key in the dictionaries and return a new dictionary.

    This function takes a variable number of dictionaries and sums the values 
    associated with the same keys. If a key is missing in some dictionaries, 
    it is treated as having a value of 0 for the purpose of summation.

    Args:
        *dicts: A variable number of dictionaries to sum values from.

    Returns:
        A new dictionary with summed values for each key.

    Example:
        dict1 = {'a': 1, 'b': 2}
        dict2 = {'a': 5, 'b': 0}
        result = _dictsum(dict1, dict2)
        # result will be {'a': 6, 'b': 2}
    """
    result: Dict[str, float] = {}

    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All inputs must be dictionaries.")

        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError(f"Value for key '{key}' must be numeric.")
            result[key] = result.get(key, 0) + value

    return result

